struct DoMoveFolder {
    destination_folder_id: String,
    folder_ids: Vec<String>,
}

impl<ServerT: ServerType> DoOperation<XpComGraphClient<ServerT>, XpComGraphError> for DoMoveFolder {
    const NAME: &'static str = "move folders";

    type Okay = ThinVec<String>;

    type Listener = SafeExchangeSimpleOperationListener;

    async fn do_operation(
        &mut self,
        client: &XpComGraphClient<ServerT>,
    ) -> Result<Self::Okay, XpComGraphError> {
        let base_api_url = client.base_api_url()?;
        let requests = self
            .folder_ids
            .iter()
            .map(|folder_id| {
                let body = mail_folder_id::r#move::PostRequestBody {
                    destination_id: Some(self.destination_folder_id.clone()),
                };
                mail_folder_id::r#move::Post::new(
                    base_api_url.to_string(),
                    folder_id.clone(),
                    OperationBody::JSON(body),
                )
            })
            .collect();

        let responses = client
            .send_batch_request_json_response(requests, Default::default())
            .await?;

        let new_folder_ids = responses
            .into_iter()
            .filter_map(|response| response.entity.id)
            .collect();

        Ok(new_folder_ids)
    }

    fn into_success_arg(
        self,
        new_folder_ids: Self::Okay,
    ) -> <Self::Listener as SafeListener>::OnSuccessArg {
        // If we have a length mismatch, that means something went wrong, but
        // perhaps not the entire request, so we need to tell the client to
        // requery the server to see what happened to the messages.
        let fallback = if new_folder_ids.len() == self.folder_ids.len() {
            UseLegacyFallback::No
        } else {
            UseLegacyFallback::Yes
        };

        let new_folder_ids = new_folder_ids.iter().map(nsCString::from).collect();
        SimpleOperationSuccessArgs {
            new_ids: new_folder_ids,
            use_legacy_fallback: fallback,
        }
    }

    fn into_failure_arg(self) -> <Self::Listener as SafeListener>::OnFailureArg {}
}

impl<ServerT: ServerType> XpComGraphClient<ServerT> {
    /// Perform a [move folders] operation.
    ///
    /// [move folders]:
    ///     https://learn.microsoft.com/en-us/graph/api/mailfolder-move
    pub(crate) async fn move_folders(
        self: Arc<XpComGraphClient<ServerT>>,
        destination_folder_id: String,
        folder_ids: Vec<String>,
        listener: SafeExchangeSimpleOperationListener,
    ) {
        let operation = DoMoveFolder {
            destination_folder_id,
            folder_ids,
        };
        operation.handle_operation(&self, &listener).await;
    }
}
